"""CRUD business logic generator."""
from __future__ import annotations

from sketchforge.generation.app_specification import AppSpec, EntitySpec, FieldSpec

from sketchforge.generation.backend.schema_generator import _py_type, _snake

# CRUD business logic
# ---------------------------------------------------------------------------

def generate_logic_py(spec: AppSpec) -> str:
    if spec.orm == "sqlalchemy":
        return _generate_sqlalchemy_logic(spec)
    lines: list[str] = [
        '"""Business logic and CRUD operations — generated by SketchForge."""',
        "from __future__ import annotations",
        "",
        "import sqlite3",
        "from typing import Optional, List",
        "from .database import connect",
        "from .models import " + ", ".join(e.name for e in spec.entities),
        "",
    ]
    for entity in spec.entities:
        lines.extend(_crud(entity))
        lines.append("")
    return "\n".join(lines)


def _generate_sqlalchemy_logic(spec: AppSpec) -> str:
    lines = ['"""SQLAlchemy CRUD operations returning JSON-ready dictionaries."""',
             'from sqlalchemy import select', 'from .database import SessionLocal',
             'from .models import ' + ', '.join(e.name for e in spec.entities), '']
    for entity in spec.entities:
        table, cls = _snake(entity.name), entity.name
        fields = ', '.join(repr(f.name) for f in entity.fields)
        lines += [f'def create_{table}(data: dict) -> dict:', '    with SessionLocal() as db:',
                  f'        obj = {cls}(**{{k: data[k] for k in ({fields},) if k in data}})',
                  '        db.add(obj); db.commit(); db.refresh(obj)', '        return _as_dict(obj)', '',
                  f'def get_{table}(item_id: int) -> dict | None:', '    with SessionLocal() as db:',
                  f'        obj = db.get({cls}, item_id)', '        return _as_dict(obj) if obj else None', '',
                  f'def list_{table}() -> list[dict]:', '    with SessionLocal() as db:',
                  f'        rows = db.scalars(select({cls}).order_by({cls}.{entity.primary_key}.desc())).all()',
                  '        return [_as_dict(row) for row in rows]', '',
                  f'def update_{table}(item_id: int, data: dict) -> dict | None:', '    with SessionLocal() as db:',
                  f'        obj = db.get({cls}, item_id)', '        if not obj: return None',
                  f'        allowed = {{{fields}}}', '        for key, value in data.items():',
                  '            if key in allowed: setattr(obj, key, value)',
                  '        db.commit(); db.refresh(obj); return _as_dict(obj)', '',
                  f'def delete_{table}(item_id: int) -> bool:', '    with SessionLocal() as db:',
                  f'        obj = db.get({cls}, item_id)', '        if not obj: return False',
                  '        db.delete(obj); db.commit(); return True', '']
    lines += ['def _as_dict(obj):', '    return {column.name: getattr(obj, column.name) for column in obj.__table__.columns}']
    return '\n'.join(lines) + '\n'


def _crud(entity: EntitySpec) -> list[str]:
    table = _snake(entity.name)
    pk = entity.primary_key
    field_names = [f.name for f in entity.fields]
    cols = ", ".join(field_names)
    placeholders = ", ".join("?" for _ in field_names)
    setters = ", ".join(f"{n} = ?" for n in field_names)

    return [
        f"# --------------- {entity.name} ---------------",
        "",
        f"def create_{table}(obj: {entity.name}) -> {entity.name}:",
        f'    """Insert a new {entity.name} and return it with the assigned id."""',
        f"    conn = connect()",
        f"    cursor = conn.execute(",
        f'        "INSERT INTO {table} ({cols}) VALUES ({placeholders})",',
        f"        [{', '.join(f'obj.{n}' for n in field_names)}],",
        f"    )",
        f"    conn.commit()",
        f"    obj.{pk} = cursor.lastrowid",
        f"    conn.close()",
        f"    return obj",
        "",
        f"def get_{table}(id: int) -> Optional[{entity.name}]:",
        f'    """Fetch one {entity.name} by primary key."""',
        f"    conn = connect()",
        f"    row = conn.execute('SELECT * FROM {table} WHERE {pk} = ?', (id,)).fetchone()",
        f"    conn.close()",
        f"    if not row: return None",
        f"    return {entity.name}(**dict(row))",
        "",
        f"def list_{table}() -> List[{entity.name}]:",
        f'    """Fetch all {entity.name} records."""',
        f"    conn = connect()",
        f"    rows = conn.execute('SELECT * FROM {table} ORDER BY {pk} DESC').fetchall()",
        f"    conn.close()",
        f"    return [{entity.name}(**dict(r)) for r in rows]",
        "",
        f"def update_{table}(obj: {entity.name}) -> bool:",
        f'    """Update an existing {entity.name}. Returns True if a row was changed."""',
        f"    conn = connect()",
        f"    cursor = conn.execute(",
        f'        "UPDATE {table} SET {setters} WHERE {pk} = ?",',
        f"        [{', '.join(f'obj.{n}' for n in field_names)}, obj.{pk}],",
        f"    )",
        f"    conn.commit()",
        f"    conn.close()",
        f"    return cursor.rowcount > 0",
        "",
        f"def delete_{table}(id: int) -> bool:",
        f'    """Delete a {entity.name} by primary key."""',
        f"    conn = connect()",
        f"    cursor = conn.execute('DELETE FROM {table} WHERE {pk} = ?', (id,))",
        f"    conn.commit()",
        f"    conn.close()",
        f"    return cursor.rowcount > 0",
    ]


# ---------------------------------------------------------------------------
